#include <bits/stdc++.h>
using namespace std;
using pii = pair<int, int>;
char s1[15][15], s2[15][15];
const int dir[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int idx[65][15][15];
int dist[15][15];
int id_counter = 1;

using llong = long long;
struct FlowEdge {
  int src, dst;
  llong capacity, flow;
  FlowEdge() : src(0), dst(0), capacity(0), flow(0) {}
  FlowEdge(int s, int d, llong cap) : src(s), dst(d), capacity(cap), flow(0) {}
};

struct DinicMaxFlow {
  int vertexCount;
  vector<FlowEdge> edges;
  vector<vector<int>> adj;
  vector<int> level, ptr;

  DinicMaxFlow(int n) : vertexCount(n), edges(), adj(n), level(n), ptr(n) {}

  void addEdge(int u, int v, llong cap) {
    if (u != v) {
      edges.emplace_back(u, v, cap);
      adj[u].push_back(edges.size() - 1);
      edges.emplace_back(v, u, 0);
      adj[v].push_back(edges.size() - 1);
    }
  }

  bool bfs(int source, int sink) {
    queue<int> q;
    q.push(source);
    fill(level.begin(), level.end(), vertexCount + 1);
    level[source] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == sink) break;
      for (int idx_edge : adj[u]) {
        FlowEdge &e = edges[idx_edge];
        if (e.flow < e.capacity && level[e.dst] > level[e.src] + 1) {
          level[e.dst] = level[e.src] + 1;
          q.push(e.dst);
        }
      }
    }
    return level[sink] <= vertexCount;
  }

  llong dfs(int u, int sink, llong bottleneck = -1) {
    if (u == sink || bottleneck == 0) return bottleneck;
    for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
      FlowEdge &e = edges[adj[u][i]];
      FlowEdge &rev = edges[adj[u][i] ^ 1];
      if (level[e.dst] == level[e.src] + 1) {
        llong available = e.capacity - e.flow;
        if (bottleneck != -1 && available > bottleneck) available = bottleneck;
        llong pushed = dfs(e.dst, sink, available);
        if (pushed > 0) {
          e.flow += pushed;
          rev.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  llong getMaxFlow(int source, int sink) {
    llong total = 0;
    while (bfs(source, sink)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (llong pushed = dfs(source, sink)) {
        total += pushed;
      }
    }
    return total;
  }
};

int main() {
  memset(dist, -1, sizeof(dist));
  int n, t;
  scanf("%d %d", &n, &t);
  for (int i = 1; i <= n; ++i) {
    scanf("%s", s1[i] + 1);
  }
  for (int layer = 0; layer <= t + 1; ++layer) {
    for (int row = 1; row <= n; ++row) {
      for (int col = 1; col <= n; ++col) {
        idx[layer][row][col] = id_counter++;
      }
    }
  }
  id_counter++;
  for (int i = 1; i <= n; ++i) {
    scanf("%s", s2[i] + 1);
  }
  queue<pii> bfsQ;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (s1[i][j] == 'Z') {
        bfsQ.emplace(i, j);
        dist[i][j] = 0;
      }
    }
  }
  while (!bfsQ.empty()) {
    auto [uy, ux] = bfsQ.front(); bfsQ.pop();
    for (int d = 0; d < 4; ++d) {
      int vy = uy + dir[d][0], vx = ux + dir[d][1];
      if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy][vx] != 'Y' && dist[vy][vx] == -1) {
        dist[vy][vx] = dist[uy][ux] + 1;
        bfsQ.emplace(vy, vx);
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (dist[i][j] == -1) dist[i][j] = 1e9;
      if (dist[i][j] > t) dist[i][j] = 1e9;
    }
  }
  int sourceNode = 0, sinkNode = id_counter - 1;
  DinicMaxFlow flowSolver(id_counter);
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (s1[i][j] >= '1' && s1[i][j] <= '9') {
        flowSolver.addEdge(sourceNode, idx[0][i][j], s1[i][j] - '0');
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (s1[i][j] == 'Y' || s1[i][j] == 'Z') continue;
      for (int k = 0; k < 4; ++k) {
        int vy = i + dir[k][0], vx = j + dir[k][1];
        if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy][vx] != 'Y' && s1[vy][vx] != 'Z') {
          for (int x = 0; x < t; ++x) {
            if (dist[vy][vx] >= x + 1 && dist[i][j] > x) {
              flowSolver.addEdge(idx[x][i][j], idx[x + 1][vy][vx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (s1[i][j] == 'Y' || s1[i][j] == 'Z') continue;
      for (int x = 0; x <= t; ++x) {
        if (s2[i][j] >= '1' && s2[i][j] <= '9') {
          flowSolver.addEdge(idx[x][i][j], idx[t + 1][i][j], s2[i][j] - '0');
        }
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (s1[i][j] == 'Y' || s1[i][j] == 'Z') continue;
      if (s2[i][j] >= '1' && s2[i][j] <= '9') {
        flowSolver.addEdge(idx[t + 1][i][j], sinkNode, s2[i][j] - '0');
      }
    }
  }
  printf("%d\n", (int)flowSolver.getMaxFlow(sourceNode, sinkNode));
  return 0;
}
